    const string Password="TemporaryTeams2026!";static int passed;
    static void Check(bool value,string name){if(!value)throw new Exception("FAIL: "+name);passed++;Console.WriteLine("PASS: "+name);}
    static async Task<JsonElement> Json(HttpResponseMessage r)=>JsonDocument.Parse(await r.Content.ReadAsStringAsync()).RootElement.Clone();
    static async Task<string> Token(HttpClient client){var html=await client.GetStringAsync("/index.html");return JsonDocument.Parse(Regex.Match(html,"<script id=\"kicks-auth-state\" type=\"application/json\">(.*?)</script>",RegexOptions.Singleline).Groups[1].Value).RootElement.GetProperty("token").GetString()!;}
    static async Task<HttpResponseMessage> Post(HttpClient c,string url,Dictionary<string,string>? data=null,bool csrf=true){data??=[];if(csrf)data["__RequestVerificationToken"]=await Token(c);return await c.PostAsync(url,new FormUrlEncodedContent(data));}
    static async Task Login(HttpClient c,string email){using var r=await Post(c,"/Pages/Auth/login.html",new(){{"Email",email},{"Password",Password}});Check(r.StatusCode==HttpStatusCode.Redirect,"fixture signs in through Identity");}
    static Dictionary<string,string> Input(string name,string version="")=>new(){{"Name",name},{"City","Amman"},{"Area","Test district"},{"Bio","Temporary SQL team"},{"Initials","SQL"},{"Capacity","5"},{"Version",version},{"Open","true"}};
    static async Task<User> Account(UserManager<User> users,string marker,string suffix,string role="player"){var u=new User{Email=marker+"-"+suffix+"@example.test",UserName=marker+"-"+suffix+"@example.test",FullName="Temporary teams "+suffix,Status="Active",LockoutEnabled=true};if(!(await users.CreateAsync(u,Password)).Succeeded||!(await users.AddToRoleAsync(u,role)).Succeeded)throw new Exception("Fixture creation failed");return u;}
