        if(cleanup){await Cleanup(db,marker);Console.WriteLine("Team browser fixtures cleaned.");return;}
        var users=scope.ServiceProvider.GetRequiredService<UserManager<User>>();foreach(var name in new[]{"captain","member","outsider","second"})await Account(users,marker,name);Console.WriteLine(JsonSerializer.Serialize(new{marker}));
    }
