            using var otherCreated=await Post(b,"/teams",Input(name.Replace(" A"," B")));Check(otherCreated.StatusCode==HttpStatusCode.Created,"another player creates another team");var otherId=(await Json(otherCreated)).GetProperty("id").GetInt32();
