            using(var r=await Post(a,$"/teams/{id}/transfer/{outsider.Id}",new(){{"Version",version}}))Check(r.StatusCode==HttpStatusCode.Conflict,"captain transfer requires an existing member");using(var r=await Post(a,$"/teams/{id}/transfer/{member.Id}",new(){{"Version",version}}))Check(r.IsSuccessStatusCode,"captaincy transfers to an existing member");Check(await db.TeamMembers.CountAsync(x=>x.TeamId==id)==2,"transfer preserves both memberships");Check(await db.BookingTeams.AnyAsync(bt=>bt.BookingId==historicalBooking.Id&&bt.CaptainId==captain.Id&&bt.TeamNameSnapshot=="Frozen squad name"),"transfer preserves historical booking captain and team-name snapshot");
