    static async Task Cleanup(KicksDbContext db,string marker)
    {
        db.ChangeTracker.Clear();var ids=await db.Users.Where(u=>u.Email!.StartsWith(marker+"-")).Select(u=>u.Id).ToListAsync();var teams=await db.Teams.Where(t=>ids.Contains(t.CaptainId)).Select(t=>t.Id).ToListAsync();var fields=await db.Fields.Where(f=>ids.Contains(f.OwnerId)).Select(f=>f.Id).ToListAsync();var logos=await db.Teams.Where(t=>teams.Contains(t.Id)).Select(t=>t.BadgeUrl).ToListAsync();await using var tx=await db.Database.BeginTransactionAsync();await db.BookingTeams.Where(bt=>teams.Contains(bt.TeamId)&&ids.Contains(bt.CaptainId)&&db.Bookings.Any(b=>b.Id==bt.BookingId&&ids.Contains(b.UserId)&&fields.Contains(b.FieldId))).ExecuteDeleteAsync();await db.Bookings.Where(b=>fields.Contains(b.FieldId)&&ids.Contains(b.UserId)).ExecuteDeleteAsync();await db.Fields.Where(f=>fields.Contains(f.Id)).ExecuteDeleteAsync();await db.TeamRequests.Where(r=>teams.Contains(r.TeamId)&&ids.Contains(r.UserId)).ExecuteDeleteAsync();await db.TeamRecruitingPositions.Where(p=>teams.Contains(p.TeamId)).ExecuteDeleteAsync();await db.TeamMembers.Where(m=>teams.Contains(m.TeamId)&&ids.Contains(m.UserId)).ExecuteDeleteAsync();await db.Teams.Where(t=>teams.Contains(t.Id)).ExecuteDeleteAsync();await db.UserRoles.Where(r=>ids.Contains(r.UserId)).ExecuteDeleteAsync();await db.UserClaims.Where(r=>ids.Contains(r.UserId)).ExecuteDeleteAsync();await db.UserLogins.Where(r=>ids.Contains(r.UserId)).ExecuteDeleteAsync();await db.UserTokens.Where(r=>ids.Contains(r.UserId)).ExecuteDeleteAsync();await db.Users.Where(u=>ids.Contains(u.Id)).ExecuteDeleteAsync();await tx.CommitAsync();foreach(var logo in logos){var safe=KicksMvc.Services.Teams.TeamService.SafeLogo(logo);if(safe is not null){var key=safe.Split('/').Last();File.Delete(Path.Combine(Directory.GetCurrentDirectory(),"App_Data","team-logos",key));}}
    }
}
